28	const BASE_PREMIUMS: Record<string, number> = {
29	  sword: 100,
30	  amulet: 60,
31	  staff: 80,
32	  potion: 40,
33	  rune: 25,
34	  moonstone: 25,
35	};
36	
37	const PROCESSING_FEE = 5;
38	
39	const WHOLE_PERCENT = 100;
40	
41	/**
42	 * Surcharges multiply before dividing, so the arithmetic stays exact.
43	 * A 1.1 multiplier would not: floating-point `100 * 1.1` is
44	 * 110.00000000000001, which rounds up to 111 and yields a 116 G premium
45	 * instead of 115 G.
46	 */
47	const addSurcharge = (amount: number, surchargePercent: number): number =>
48	  (amount * (WHOLE_PERCENT + surchargePercent)) / WHOLE_PERCENT;
49	
50	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
51	
52	/** All rounding is in the MHPCO's favor — always up. */
53	const roundInMHPCOsFavor = Math.ceil;
54	
55	const sumBasePremiums = (items: InsuredItem[]): number =>
56	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
57	
58	const quotePremium = (step: Step): QuoteResult => {
59	  const base = sumBasePremiums(step.items ?? []);
60	  const withSurcharge = addSurcharge(base, FIRST_INSURANCE_SURCHARGE_PERCENT);
61	
62	  return {
63	    premium: roundInMHPCOsFavor(withSurcharge) + PROCESSING_FEE,
64	  };
65	};
66	
67	export const runScenario = (scenario: Scenario): ScenarioResults => ({
68	  results: scenario.steps.map(quotePremium),
69	});
