/**
 * The premium pipeline, in the order the spec states it: sum the base
 * premiums, apply surcharges, round, then add the processing fee last.
 */
const quotePremium = (step: Step): QuoteResult => {
  const basePremium = sumBasePremiums(step.items ?? []);
  const surcharged = addSurcharge(
    basePremium,
    FIRST_INSURANCE_SURCHARGE_PERCENT,
  );

  return { premium: roundInMHPCOsFavor(surcharged) + PROCESSING_FEE };
};
